import { timestamp, uuid } from "drizzle-orm/pg-core";

/** UUID primary key generated by the database. */
export const id = () => uuid("id").primaryKey().defaultRandom();

/**
 * created_at / updated_at, timestamptz, UTC. updated_at is kept current by the
 * set_updated_at() trigger (migration 0002), which also covers raw SQL, so
 * there is deliberately no $onUpdate here: one source of truth.
 */
export const timestamps = () => ({
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});
